DROP TABLE IF EXISTS pagos;
DROP TABLE IF EXISTS afiliados;
CREATE TABLE afiliados (id INT PRIMARY KEY, nombre TEXT NOT NULL, pais CHAR(2) NOT NULL, edad INT NOT NULL, activo BOOLEAN NOT NULL);
CREATE TABLE pagos (id INT PRIMARY KEY, afiliado_id INT NOT NULL REFERENCES afiliados(id), fecha DATE NOT NULL, monto NUMERIC(10,2) NOT NULL, estado TEXT NOT NULL);
ANALYZE afiliados;
ANALYZE pagos;
